node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Begin transaction for the swap
const transaction = db.transaction(() => {
  // 1. Update the order item: swap to Olive/M variant
  db.prepare(\"UPDATE order_items SET item_id = '2364909101', options = '{\\\"color\\\": \\\"Olive\\\", \\\"size\\\": \\\"M\\\"}', unit_price = 53.89 WHERE oi_id = 'RT-#W4705780-0'\").run();

  // 2. Update order status and record exchange details
  db.prepare(\"UPDATE orders SET status = 'pending (items modified)', exchange_items = '[\\\"9716794911\\\"]', exchange_new_items = '[\\\"2364909101\\\"]', exchange_payment_method_id = 'credit_card_5360334', exchange_price_difference = -1.10 WHERE order_id = '#W4705780'\").run();

  // 3. Update the subtotal and total_paid to reflect the price difference
  // Old subtotal: 54.99 + 24.99 = 79.98, New: 53.89 + 24.99 = 78.88
  db.prepare(\"UPDATE orders SET subtotal = 78.88, total_paid = 78.88 WHERE order_id = '#W4705780'\").run();
});

transaction();

// Verify the changes
const order = db.prepare(\"SELECT * FROM orders WHERE order_id = '#W4705780'\").get();
console.log('=== Updated Order ===');
console.log(JSON.stringify(order, null, 2));

const items = db.prepare(\"SELECT * FROM order_items WHERE order_id = '#W4705780'\").all();
console.log('=== Updated Order Items ===');
console.log(JSON.stringify(items, null, 2));
"
